python3 << 'EOF'
import paramiko
c = paramiko.SSHClient()
c.set_missing_host_key_policy(paramiko.AutoAddPolicy())
c.connect('46.202.154.25', 22, 'root', '2N00py123+++')

# Update build.gradle with SDK 24/34
update = '''apply plugin: 'com.android.application'

android {
    namespace 'com.ouroboros.arelorian'
    compileSdk 34

    defaultConfig {
        applicationId "com.ouroboros.arelorian"
        minSdk 24
        targetSdk 34
        versionCode 1
        versionName "1.0.0"
        multiDexEnabled true
    }

    buildTypes {
        release {
            minifyEnabled true
            shrinkResources true
            proguardFiles getDefaultProguardFile('proguard-android-optimize.txt'), 'proguard-rules.pro'
        }
        debug {
            minifyEnabled false
            debuggable true
        }
    }

    compileOptions {
        sourceCompatibility JavaVersion.VERSION_11
        targetCompatibility JavaVersion.VERSION_11
    }

    packaging {
        resources {
            excludes += ['META-INF/NOTICE.md', 'META-INF/LICENSE.md']
        }
    }
}

dependencies {
    implementation 'androidx.appcompat:appcompat:1.6.1'
    implementation 'androidx.core:core-ktx:1.12.0'
    implementation 'androidx.activity:activity:1.8.2'
    implementation 'com.google.android.material:material:1.11.0'
    implementation 'androidx.multidex:multidex:2.0.1'
    implementation project(':capacitor-android')
}
'''

sftp = c.open_sftp()
with sftp.file('/tmp/build.gradle', 'w') as f:
    f.write(update)

c.exec_command('cp /tmp/build.gradle /opt/areloria/client/android/app/build.gradle')
print('build.gradle updated to SDK 24/34')

# Check for icons
stdin, stdout, stderr = c.exec_command("ls /opt/areloria/client/android/app/src/main/res/ 2>/dev/null | head -10")
print("Res:", stdout.read().decode())

c.close()
EOF

